content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #d1d5db;
  --accent-color: #10b981;
  --error-color: #ef4444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

body {
  background-color: var(--bg-color);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

.app-container {
  width: 100%;
  max-width: 600px;
  margin: 0 auto;
  padding: 24px;
  background-color: var(--card-bg);
  border-radius: 16px;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.05);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
}

.game-header {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

.timer-box, .score-box {
  background-color: var(--bg-color);
  padding: 10px 20px;
  border-radius: 8px;
  font-weight: bold;
  font-size: 1.1rem;
  color: var(--text-main);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.word-display {
  width: 100%;
  background-color: #faf5ff;
  border: 2px solid #e9d5ff;
  border-radius: 12px;
  padding: 32px 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  text-align: center;
  cursor: pointer;
}

.jp-word {
  font-size: 2rem;
  font-weight: bold;
  color: #6b21a8;
}

.romaji-word {
  font-size: 1.5rem;
  font-family: monospace;
  color: var(--text-muted);
  letter-spacing: 2px;
}

.input-field {
  width: 100%;
  padding: 16px;
  font-size: 1.5rem;
  font-family: monospace;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  text-align: center;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-field:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.2);
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-4px); }
  40%, 80% { transform: translateX(4px); }
}

.input-field.error {
  border-color: var(--error-color);
  box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.2);
  animation: shake 0.3s ease-in-out;
}

.btn {
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: bold;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
  width: 100%;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.result-card {
  width: 100%;
  display: flex;
  flex-direction: column;
  gap: 20px;
  align-items: center;
  text-align: center;
}

.stat-grid {
  width: 100%;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.stat-item {
  background-color: var(--bg-color);
  padding: 16px;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.stat-item span:first-child {
  font-size: 0.9rem;
  color: var(--text-muted);
}

.stat-item span:last-child {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--primary-color);
}

@media (max-width: 480px) {
  body {
    align-items: flex-start;
    padding: 12px;
  }

  .app-container {
    padding: 16px;
    margin: 0;
    max-width: 100%;
    border-radius: 12px;
    gap: 16px;
  }

  .game-header {
    gap: 8px;
  }

  .timer-box, .score-box {
    padding: 8px 12px;
    font-size: 0.95rem;
  }

  .word-display {
    padding: 20px 12px;
    gap: 8px;
  }

  .jp-word {
    font-size: 1.5rem;
  }

  .romaji-word {
    font-size: 1.1rem;
    letter-spacing: 1px;
  }

  .input-field {
    padding: 12px;
    font-size: 1.2rem;
  }

  .stat-grid {
    gap: 8px;
  }

  .stat-item {
    padding: 12px;
  }

  .stat-item span:last-child {
    font-size: 1.2rem;
  }
}

export type GameState = 'start' | 'playing' | 'result';

export type Difficulty = 'easy' | 'normal' | 'hard';

export interface WordItem {
  japanese: string;
  roman: string;
  difficulty?: Difficulty;
  category?: string;
}

export interface GameStats {
  totalTyped: number;
  correctChars: number;
  errorChars: number;
  accuracy: number;
}

import { useRef, useEffect } from 'react';
import { WordItem } from '../types';
import '../index.css';

interface TypingGameProps {
  word: WordItem;
  userInput: string;
  onUserInputChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  timeLeft: number;
  score: number;
}

export default function TypingGame({
  word,
  userInput,
  onUserInputChange,
  timeLeft,
  score,
}: TypingGameProps) {
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
  }, [word]);

  const currentRoman = word?.roman || '';
  const typedPart = currentRoman.slice(0, userInput.length);
  const untypedPart = currentRoman.slice(userInput.length);

  return (
    <div aria-label="タイピングゲームプレイ画面" role="region">
      <div className="game-header">
        <div className="timer-box" aria-live="polite">
          <span>残り時間</span>
          <span>{timeLeft}秒</span>
        </div>
        <div className="score-box" aria-live="polite">
          <span>スコア（文字数）</span>
          <span>{score}</span>
        </div>
      </div>

      <div className="word-display" onClick={() => inputRef.current?.focus()}>
        <div className="jp-word">{word?.japanese || ''}</div>
        <div className="romaji-word" aria-label={`ローマ字: ${currentRoman}`}>
          <span style={{ color: 'var(--primary-color)', fontWeight: 'bold' }}>{typedPart}</span>
          <span style={{ color: 'var(--text-muted)' }}>{untypedPart}</span>
        </div>
      </div>

      <input
        ref={inputRef}
        type="text"
        className="input-field"
        value={userInput}
        onChange={onUserInputChange}
        placeholder="ここに入力..."
        autoComplete="off"
        autoCapitalize="off"
        autoCorrect="off"
        spellCheck="false"
        aria-label="ローマ字入力フィールド"
      />
    </div>
  );
}

import { GameStats } from '../types';
import '../index.css';

interface ResultModalProps {
  stats: GameStats;
  onRestart: () => void;
}

export default function ResultModal({ stats, onRestart }: ResultModalProps) {
  const getEvaluationMessage = (accuracy: number, total: number) => {
    if (total === 0) return 'まずはプレイしてみましょう！';
    if (accuracy >= 95 && total >= 50) return 'すばらしい！プロレベルのタイピングです！';
    if (accuracy >= 85) return 'とても上手です！その調子！';
    if (accuracy >= 70) return 'よくできました！さらにスピードを上げてみよう。';
    return 'もう少し！練習を重ねてスピードアップを目指そう！';
  };

  const message = getEvaluationMessage(stats.accuracy, stats.totalTyped);

  return (
    <div className="result-card" role="dialog" aria-modal="true" aria-label="ゲーム結果画面">
      <h2>ゲーム終了！</h2>
      <p style={{ color: 'var(--primary-color)', fontWeight: 'bold', fontSize: '1.1rem' }}>
        {message}
      </p>
      <div className="stat-grid">
        <div className="stat-item">
          <span>総打鍵数</span>
          <span>{stats.totalTyped}</span>
        </div>
        <div className="stat-item">
          <span>正解文字数</span>
          <span>{stats.correctChars}</span>
        </div>
        <div className="stat-item">
          <span>ミス文字数</span>
          <span>{stats.errorChars}</span>
        </div>
        <div className="stat-item">
          <span>正解率</span>
          <span>{stats.accuracy}%</span>
        </div>
      </div>
      <button className="btn btn-primary" onClick={onRestart}>
        もう一度プレイする
      </button>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { GameState, WordItem, GameStats } from './types';
import TypingGame from './components/TypingGame';
import ResultModal from './components/ResultModal';
import './index.css';

const WORD_LIST: WordItem[] = [
  { japanese: 'りんご', roman: 'ringo' },
  { japanese: 'パソコン', roman: 'pasokon' },
  { japanese: 'プログラミング', roman: 'puroguramingu' },
  { japanese: 'タイピング', roman: 'taipingu' },
  { japanese: 'ねこ', roman: 'neko' },
  { japanese: 'いぬ', roman: 'inu' },
  { japanese: 'すし', roman: 'sushi' },
  { japanese: 'さくら', roman: 'sakura' },
  { japanese: 'おにぎり', roman: 'onigiri' },
  { japanese: '富士山', roman: 'fujisan' },
  { japanese: 'きつね', roman: 'kitsune' },
  { japanese: 'ひまわり', roman: 'himawari' },
  { japanese: 'たこやき', roman: 'takoyaki' },
  { japanese: 'しょうゆ', roman: 'shouyu' },
  { japanese: 'てんぷら', roman: 'tempura' },
];

export default function App() {
  const [gameState, setGameState] = useState<GameState>('start');
  const [currentWordIndex, setCurrentWordIndex] = useState<number>(0);
  const [userInput, setUserInput] = useState<string>('');
  const [timeLeft, setTimeLeft] = useState<number>(60);
  const [score, setScore] = useState<number>(0);

  const [stats, setStats] = useState<GameStats>({
    totalTyped: 0,
    correctChars: 0,
    errorChars: 0,
    accuracy: 100,
  });

  const [shuffledWords, setShuffledWords] = useState<WordItem[]>(WORD_LIST);

  const [highScore, setHighScore] = useState<number>(() => {
    const saved = localStorage.getItem('typing_high_score');
    return saved ? parseInt(saved, 10) : 0;
  });

  const startGame = () => {
    const shuffled = [...WORD_LIST].sort(() => Math.random() - 0.5);
    setShuffledWords(shuffled);
    setCurrentWordIndex(0);
    setUserInput('');
    setTimeLeft(60);
    setScore(0);
    setStats({
      totalTyped: 0,
      correctChars: 0,
      errorChars: 0,
      accuracy: 100,
    });
    setGameState('playing');
  };

  const endGame = useCallback(() => {
    setGameState('result');
    setStats((prev) => {
      const total = prev.correctChars + prev.errorChars;
      const acc = total > 0 ? Math.round((prev.correctChars / total) * 100) : 100;
      return {
        ...prev,
        totalTyped: total,
        accuracy: acc,
      };
    });
  }, []);

  useEffect(() => {
    if (gameState === 'result') {
      if (score > highScore) {
        setHighScore(score);
        localStorage.setItem('typing_high_score', score.toString());
      }
    }
  }, [gameState, score, highScore]);

  useEffect(() => {
    if (gameState !== 'playing') return;

    if (timeLeft <= 0) {
      endGame();
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState, timeLeft, endGame]);

  const handleUserInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState !== 'playing') return;
    const value = e.target.value;
    const currentWord = shuffledWords[currentWordIndex];

    if (!currentWord) return;

    if (currentWord.roman.startsWith(value)) {
      if (value.length > userInput.length) {
        setStats((prev) => ({
          ...prev,
          correctChars: prev.correctChars + 1,
        }));
      }
      setUserInput(value);

      // Completed the word
      if (value === currentWord.roman) {
        setScore((prev) => prev + currentWord.roman.length);
        setUserInput('');
        setCurrentWordIndex((prev) => (prev + 1) % shuffledWords.length);
      }
    } else {
      if (value.length > userInput.length) {
        setStats((prev) => ({
          ...prev,
          errorChars: prev.errorChars + 1,
        }));
      }
    }
  };

  return (
    <div className="app-container">
      {gameState === 'start' && (
        <div className="result-card">
          <h2>ローマ字タイピングゲーム</h2>
          <p style={{ color: 'var(--text-muted)' }}>
            60秒間でできるだけ多くの日本語をローマ字で入力しよう！
          </p>
          {highScore > 0 && (
            <p style={{ fontWeight: 'bold', color: 'var(--primary-color)' }}>
              ハイスコア: {highScore}点
            </p>
          )}
          <button className="btn btn-primary" onClick={startGame}>
            ゲームスタート
          </button>
        </div>
      )}

      {gameState === 'playing' && (
        <TypingGame
          word={shuffledWords[currentWordIndex] || WORD_LIST[0]}
          userInput={userInput}
          onUserInputChange={handleUserInputChange}
          timeLeft={timeLeft}
          score={score}
        />
      )}

      {gameState === 'result' && (
        <div className="result-card">
          {score > highScore && (
            <p style={{ color: 'var(--accent-color)', fontWeight: 'bold' }}>
              🎉 ハイスコア更新！ ({score}点)
            </p>
          )}
          <ResultModal stats={stats} onRestart={startGame} />
        </div>
      )}
    </div>
  );
}
